// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport com.roshan.persona.common.CorrelationId/** * NOUS — Agentic step (one action in a ReAct workflow). * * The ReAct (Reason + Act) pattern alternates between: *   1. **Thought** — LLM reasons about the current state and what to do next *   2. **Action** — LLM picks an action: call a tool, query itself, or final answer *   3. **Observation** — result of the action (fed back into next Thought) * * This sealed hierarchy represents the Action step. The Thought is stored * alongside the action in [WorkflowStep.thought]. * * ## Step Types * *   - [Thought] — LLM's reasoning (stored separately in WorkflowStep) *   - [ToolCall] — invoke a registered [AgenticTool] with parameters *   - [LlmQuery] — ask the LLM a follow-up question (no tool needed) *   - [FinalAnswer] — workflow complete, return this answer to user * * ## Privacy * *   - Tool parameters may contain user data, but are NEVER sent to cloud LLM *     unless the tool itself is a cloud tool. *   - LLM queries are scrubbed of PII before being sent (same as Layer 3/4). * * @see <a href="docs/spec/module2-spec-review.pdf">§9 Layer 5</a> */sealed interface AgenticStep {    /**     * Invoke a registered [AgenticTool] with parameters.     *     * @property toolId the tool's ID (must be registered in [AgenticToolRegistry])     * @property params tool-specific parameters (validated by the tool)     */    data class ToolCall(        val toolId: String,        val params: Map<String, String>,    ) : AgenticStep {        init {            require(toolId.isNotBlank()) { "Tool ID cannot be blank" }        }    }    /**     * Ask the LLM a follow-up question (no tool call needed).     *     * Used when the LLM needs to reason about previous observations or     * synthesize information before producing a final answer.     *     * @property prompt the question to ask the LLM     */    data class LlmQuery(        val prompt: String,    ) : AgenticStep {        init {            require(prompt.isNotBlank()) { "LLM query prompt cannot be blank" }        }    }    /**     * Workflow complete — return this answer to the user.     *     * The orchestrator stops the ReAct loop and returns this as the final     * output. No further steps are executed.     *     * @property answer the final answer text     */    data class FinalAnswer(        val answer: String,    ) : AgenticStep {        init {            require(answer.isNotBlank()) { "Final answer cannot be blank" }        }    }}/** * Result of executing an [AgenticStep]. * * Returned by [AgenticExecutor] after running a step. The [AgenticCritic] * evaluates this to decide the next action. */sealed interface AgenticStepResult {    /** Correlation ID for tracing. */    val correlationId: CorrelationId    /** Wall-clock duration of the step execution, in milliseconds. */    val durationMs: Long    /** USD cost of this step (0 for free tools, >0 for LLM calls). */    val costUsd: Float    /**     * Tool call succeeded.     *     * @property toolId which tool was called     * @property output human-readable output (fed back to LLM as observation)     * @property data structured data (for audit log, not sent to LLM)     */    data class ToolSuccess(        val toolId: String,        val output: String,        val data: Map<String, Any?> = emptyMap(),        override val correlationId: CorrelationId,        override val durationMs: Long,        override val costUsd: Float = 0f,    ) : AgenticStepResult    /**     * Tool call failed.     *     * @property toolId which tool was called     * @property error human-readable error message (fed back to LLM)     * @property retryable whether the critic should retry this step     */    data class ToolFailure(        val toolId: String,        val error: String,        val retryable: Boolean,        override val correlationId: CorrelationId,        override val durationMs: Long,        override val costUsd: Float = 0f,    ) : AgenticStepResult    /**     * LLM query succeeded.     *     * @property text the LLM's response     * @property tokensUsed total tokens consumed (input + output)     */    data class LlmSuccess(        val text: String,        val tokensUsed: Int,        override val correlationId: CorrelationId,        override val durationMs: Long,        override val costUsd: Float,    ) : AgenticStepResult    /**     * LLM query failed (timeout, OOM, network error).     *     * @property error human-readable error message     * @property retryable whether the critic should retry     */    data class LlmFailure(        val error: String,        val retryable: Boolean,        override val correlationId: CorrelationId,        override val durationMs: Long,        override val costUsd: Float = 0f,    ) : AgenticStepResult    /**     * Final answer was produced (no execution needed — the step itself IS     * the answer).     */    data class FinalAnswerProduced(        val answer: String,        override val correlationId: CorrelationId,        override val durationMs: Long = 0L,        override val costUsd: Float = 0f,    ) : AgenticStepResult}